// #8140c180a9bf2e83d1a17783 (комментарий программиста про RowMenu) — меню строки «⋮» на /admin/support,
// открытое на узком окне (700), после расширения до 1440 открывается с той же шириной, что и сразу на 1440.
// Кейс SUP-002. Только чтение (меню открывается и закрывается, пункты не нажимаются) — @prod-safe.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

/** Открыть меню первой строки, где оно есть; вернуть его прямоугольник; закрыть (Esc). */
async function openMenuAndMeasure(page: Page) {
  const button = page.getByRole('button', { name: /^פעולות/ }).first();
  await button.scrollIntoViewIfNeeded();
  await button.click();
  const menu = page.getByRole('menu');
  await expect(menu).toBeVisible();
  const box = await menu.evaluate((m) => {
    const r = m.getBoundingClientRect();
    return { left: r.left, right: r.right, width: r.width, vw: window.innerWidth };
  });
  await page.keyboard.press('Escape');
  await expect(menu).toBeHidden();
  return box;
}

test.describe('Поддержка — меню строки после смены ширины (#8140c180a9bf2e83d1a17783)', () => {
  test('меню строки после 700 → 1440 не залипает узким и целиком в окне @desktop @prod-safe #8140c180a9bf2e83d1a17783', async ({ asUser }) => {
    const page = await asUser('admin');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/support');
    await expect(page.getByRole('button', { name: /^פעולות/ }).first()).toBeVisible();

    const fresh = await openMenuAndMeasure(page);
    await page.setViewportSize({ width: 700, height: 900 });
    await openMenuAndMeasure(page);
    await page.setViewportSize({ width: 1440, height: 900 });
    const after = await openMenuAndMeasure(page);

    // Источник: комментарий программиста — ширина меню не должна запоминаться с прошлого измерения.
    expect(Math.abs(after.width - fresh.width), `ширина меню: сразу ${fresh.width}, после 700→1440 ${after.width}`).toBeLessThanOrEqual(1);
    expect(after.left).toBeGreaterThanOrEqual(0);
    expect(after.right).toBeLessThanOrEqual(after.vw);
  });
});
